import { normalizePhone } from "./contact-import.ts";

export type CampaignSelection =
  | { kind: "all" }
  | { kind: "category"; value: string }
  | { kind: "side"; value: "חתן" | "כלה" | "משותף" }
  | { kind: "not_sent" }
  | { kind: "unanswered" }
  | { kind: "manual"; guestIds: ReadonlySet<string> };

export type CampaignCandidate = {
  guestId: string;
  fullName: string;
  phone: string | null;
  category: string | null;
  side: string | null;
  rsvpStatus: "awaiting" | "partial" | "confirmed" | "declined" | null;
  lastInvitationSentAt: string | null;
  /** Generated by the existing RSVP link lifecycle, and kept in memory only. */
  rsvpLink: string | null;
};

export type CampaignVariables = {
  coupleNames: string;
  weddingDate: string;
  venueName: string;
};

export type RecipientPreview = {
  guestId: string;
  fullName: string;
  normalizedPhone: string | null;
  message: string | null;
  problems: readonly (
    "invalid_phone" | "duplicate_phone" | "missing_name" | "missing_link" | "missing_variable"
  )[];
};

const TOKENS = {
  $שם_פרטי: "firstName",
  $שמות_הזוג: "coupleNames",
  $תאריך_החתונה: "weddingDate",
  $שם_האולם: "venueName",
  $קישור: "rsvpLink",
} as const;

function matches(candidate: CampaignCandidate, selection: CampaignSelection): boolean {
  switch (selection.kind) {
    case "all":
      return true;
    case "category":
      return candidate.category === selection.value;
    case "side":
      return candidate.side === selection.value;
    case "not_sent":
      return candidate.lastInvitationSentAt === null;
    case "unanswered":
      return (
        candidate.rsvpStatus === null ||
        candidate.rsvpStatus === "awaiting" ||
        candidate.rsvpStatus === "partial"
      );
    case "manual":
      return selection.guestIds.has(candidate.guestId);
  }
}

/** Produces an in-memory preview only. It does not issue links, schedule, queue or send. */
export function prepareCampaignPreview(
  candidates: readonly CampaignCandidate[],
  selection: CampaignSelection,
  template: string,
  variables: CampaignVariables,
): RecipientPreview[] {
  if (!template.trim()) throw new Error("יש להזין תוכן הודעה");
  const unknownTokens = [...template.matchAll(/\$[\p{L}_]+/gu)]
    .map((match) => match[0])
    .filter((token) => !(token in TOKENS));
  if (unknownTokens.length) throw new Error(`משתנה הודעה לא מוכר: ${unknownTokens[0]}`);

  const seenPhones = new Set<string>();
  const selected = candidates.filter((candidate) => matches(candidate, selection));
  const seenGuests = new Set<string>();
  return selected.map((candidate) => {
    if (seenGuests.has(candidate.guestId)) throw new Error("רשימת הנמענים מכילה קבוצת הזמנה כפולה");
    seenGuests.add(candidate.guestId);
    const normalizedPhone = candidate.phone ? normalizePhone(candidate.phone) : null;
    const firstName = candidate.fullName.trim().split(/\s+/u)[0] ?? "";
    const problems: RecipientPreview["problems"][number][] = [];
    if (!normalizedPhone) problems.push("invalid_phone");
    else if (seenPhones.has(normalizedPhone)) problems.push("duplicate_phone");
    if (normalizedPhone) seenPhones.add(normalizedPhone);
    if (!firstName) problems.push("missing_name");
    if (!candidate.rsvpLink) problems.push("missing_link");

    const values: Record<(typeof TOKENS)[keyof typeof TOKENS], string> = {
      firstName,
      coupleNames: variables.coupleNames.trim(),
      weddingDate: variables.weddingDate.trim(),
      venueName: variables.venueName.trim(),
      rsvpLink: candidate.rsvpLink ?? "",
    };
    for (const [token, field] of Object.entries(TOKENS)) {
      if (template.includes(token) && !values[field as keyof typeof values]) {
        if (field !== "firstName" && field !== "rsvpLink") problems.push("missing_variable");
      }
    }
    const message = problems.length
      ? null
      : template.replace(/\$[\p{L}_]+/gu, (token) => values[TOKENS[token as keyof typeof TOKENS]]);
    return {
      guestId: candidate.guestId,
      fullName: candidate.fullName,
      normalizedPhone,
      message,
      problems,
    };
  });
}
